import {
	Accessor,
	createEffect,
	createSignal,
	JSX,
	mergeProps,
	ParentComponent,
	ParentProps,
	Setter,
	Show,
} from "solid-js";

import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";

interface AccordianHeaderProps {
	class?: string;
	style?: JSX.CSSProperties;
	isCollapsed: Accessor<boolean>;
	setIsCollapsed: Setter<boolean>;
}

const AccordianHeader: ParentComponent<AccordianHeaderProps> = (props) => {
	const audioTrigger = useAudio();

	return (
		<Activatable
			class={`accordian-header w-full flex flex-row items-center relative group ${props.class ?? ""}`}
			style={props.style}
			onActivate={() => {
				props.setIsCollapsed((value) => !value);
				if (props.isCollapsed()) {
					audioTrigger("dropdown-close");
				} else {
					audioTrigger("dropdown-open");
				}
			}}
			data-name="accordian-header"
			audioComponentAlias="AccordianHeader"
		>
			{props.children}
		</Activatable>
	);
};

export interface AccordianProps extends JSX.HTMLAttributes<HTMLDivElement> {
	header: JSX.Element;
	headerStyle?: JSX.CSSProperties;
	headerClass?: string;
	// Default: "expanded"
	expandedStyle?: string;
	// Default: "collapsed"
	collapsedStyle?: string;
	initialCollapsed?: boolean;
	setIsCollapsed?: Setter<boolean>;
}

export function Accordian(props: ParentProps<AccordianProps>) {
	const [isCollapsed, setIsCollapsed] = createSignal(props.initialCollapsed ?? false);

	const defaultProps = mergeProps({ expandedStyle: "expanded", collapsedStyle: "collapsed" }, props);

	createEffect(() => {
		if (props.setIsCollapsed) {
			props.setIsCollapsed(isCollapsed());
		}
	});

	return (
		<div
			{...props}
			class={`accordian flex flex-col ${isCollapsed() ? defaultProps.collapsedStyle : defaultProps.expandedStyle} ${props.class ?? ""}`}
		>
			<AccordianHeader
				class={props.headerClass}
				style={props.headerStyle}
				isCollapsed={isCollapsed}
				setIsCollapsed={setIsCollapsed}
			>
				{props.header}
			</AccordianHeader>
			<Show when={!isCollapsed()}>{props.children}</Show>
		</div>
	);
}
